export const emptySound=()=>({uri:'',name:''});
export const defaultAlerts=()=>({notification:emptySound(),alarm:emptySound(),volumeDismiss:true});
export function upgradeAlerts(s){if(s?.version!==2)return s;s.settings.alerts??=defaultAlerts();for(const m of s.missions){m.alerts??={alarms:[],dueAlarm:false,notification:emptySound(),alarm:emptySound()};}validateAlerts(s);return s;}
export function validateAlerts(s){const sound=x=>x&&typeof x.uri==='string'&&x.uri.length<3000&&(!x.uri||/^content:\/\//.test(x.uri))&&typeof x.name==='string'&&x.name.length<512;const a=s.settings.alerts;if(!a||!sound(a.notification)||!sound(a.alarm)||typeof a.volumeDismiss!=='boolean')throw Error('Invalid reminder sound settings.');for(const m of s.missions){const c=m.alerts;if(!c||!Array.isArray(c.alarms)||c.alarms.length>5||!c.alarms.every(x=>typeof x==='boolean')||typeof c.dueAlarm!=='boolean'||!sound(c.notification)||!sound(c.alarm))throw Error('Invalid mission alert settings.');}}
export function resolveAlert(m,event,settings){const index=/:pre:(\d+)$/.exec(event.id),alarm=index?!!m.alerts?.alarms[+index[1]]:!!m.alerts?.dueAlarm,type=alarm?'alarm':'notification',local=m.alerts?.[type],global=settings.alerts?.[type];return {...event,type,sound:local?.uri||global?.uri||'',volumeDismiss:settings.alerts?.volumeDismiss!==false};}
